import React, { useState, useEffect } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import ListingModal from "../Components/ListingModal";
import "../styles/AdminPages.css";
import API_BASE_URL from "../config";

const MyFlaggedListings = () => {
  const [flagged, setFlagged] = useState([]);
  const [selectedListing, setSelectedListing] = useState(null);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (!userId) return;

    fetch(`${API_BASE_URL}/api/listings/flagged/${userId}`)
      .then((res) => res.json())
      .then((data) => {
        console.log("📦 MyFlaggedListings API Response:", data);
        if (Array.isArray(data)) {
          setFlagged(data);
        } else {
          console.warn("Unexpected data:", data);
          setFlagged([]);
        }
      })
      .catch((err) => {
        console.error("🚨 Failed to load flagged listings:", err);
        setFlagged([]);
      });
  }, [userId]);

  const unflagListing = async (listingId) => {
    const res = await fetch(`${API_BASE_URL}/api/listings/flagged/${userId}/${listingId}`, {
      method: "DELETE",
    });

    if (res.ok) {
      setFlagged(flagged.filter((item) => item.listing_id !== listingId));
    } else {
      alert("❌ Failed to unflag listing.");
    }
  };

  return (
    <div>
      <Navbar />
      <main className="favorites-wrapper">
        <h2>My Flagged Listings</h2>
        <div className="favorites-grid">
          {flagged.length === 0 ? (
            <p>You haven’t flagged any listings yet.</p>
          ) : (
            flagged.map((item) => {
              console.log("🧩 Rendering flagged item:", item);
              return (
                <div className="favorite-card" key={item.id || item.listing_id}>
                  <img
                    src={item.image || "https://via.placeholder.com/300x200?text=No+Image"}
                    alt={item.title || "Listing"}
                    onError={(e) => {
                      e.target.src = "https://via.placeholder.com/300x200?text=No+Image";
                    }}
                  />
                  <h4>{item.title || "No Title"}</h4>
                  <p>{item.description || "No description provided."}</p>
                  <p><strong>Condition:</strong> {item.condition || "N/A"}</p>
                  <p><strong>Price:</strong> ${item.price || "0.00"}</p>
                  <p><strong>Flag Reason:</strong> {item.reason}</p>
                  <p><strong>Listed On:</strong> {item.created_at ? new Date(item.created_at).toLocaleDateString() : "N/A"}</p>
                  <button className="listing-btn" onClick={() => setSelectedListing(item)}>
                    View Details
                  </button>
                  <button className="remove-btn" onClick={() => unflagListing(item.listing_id)}>
                    Unflag
                  </button>
                </div>
              );
            })
          )}
        </div>
      </main>

      {/* Modal */}
      {selectedListing && (
        <ListingModal item={selectedListing} onClose={() => setSelectedListing(null)} />
      )}

      <Footer />
    </div>
  );
};

export default MyFlaggedListings;
